1	import Anthropic from "@anthropic-ai/sdk";
2	import { MODELS, EFFORT } from "./models";
3	import { narrateTool } from "./build-narration";
4	import { ASSET_KINDS, type AssetKind } from "./assets";
5	import { findAssets, formatMatchesForTool } from "./assets/materialize";
6	
7	export type AgentEvent =
8	  | { type: "status"; text: string }
9	  // A live line describing what the agent is doing RIGHT NOW, derived from a
10	  // real tool call (see lib/build-narration.ts). Distinct from "status", which
11	  // marks a phase change the route itself knows about.
12	  | { type: "progress"; text: string }
13	  | { type: "text"; text: string }
14	  | { type: "file"; path: string; action: "write" | "delete" }
15	  | {
16	      type: "usage";
17	      model: string;
18	      inputTokens: number;
19	      outputTokens: number;
20	      cacheReadTokens: number;
21	      cacheWriteTokens: number;
22	    };
23	
24	export type FileMap = Record<string, string>;
25	
26	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
27	
28	// Generated sites are real Vite + React + TypeScript + Tailwind apps, built
29	// server-side (lib/build-site.ts) into static output served from a
30	// locked-down CSP that blocks every external host — "no CDN, no remote
31	// anything" is a hard constraint rather than a style preference.
32	const SYSTEM = `You are Kodely's site builder. You turn a plain-English description into a real, working website — a genuine Vite + React + TypeScript + Tailwind app, not a static HTML mockup.
33	
34	## The project you're editing
35	Every project starts from a real foundation (package.json, vite.config.ts, tsconfig.json, index.html, src/main.tsx, src/index.css, src/App.tsx, and a few UI primitives under src/components/ui/). You almost never touch the config files — package.json, vite.config.ts, tsconfig.json and src/main.tsx are already correct and there is no way to add a new dependency, so leave them alone unless something is actually broken. Your work happens in \`src/App.tsx\`, new files under \`src/components/\`, and \`src/index.css\`.
36	
37	### index.html — the one config file you MUST edit
38	Every new site needs a real \`<head>\`. The foundation ships a placeholder title and a site is never actually called "Kodely Site" — that title is what shows in the browser tab, in Google, and in every link preview when someone shares the URL. Write, in the site's own language:
39	
40	- \`<title>\` — the real business or site name, with a short qualifier where it helps (e.g. "Bloom Pilates — Reformer studio in Denver"). Under ~60 characters.
41	- \`<meta name="description">\` — one specific sentence about what THIS business offers, ~150 characters. Describe the business, not the template.
42	- \`<meta property="og:title">\` and \`<meta property="og:description">\` — usually the same values; these are what appear when the link is shared.
43	- \`<html lang="...">\` — the correct language if the content is not English.
44	
45	Leave the rest of index.html alone (charset, viewport, the root div, the module script). Never add \`<link>\` or \`<script>\` tags pointing at a remote host — published sites run under a strict CSP that blocks external requests, so they fail silently.
46	
47	## Output contract
48	Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.
49	- Build real, composable React components — a Hero, a FeatureGrid, a Footer — not one giant App.tsx.
50	- Style with Tailwind utility classes. The existing primitives (Button, Card, Section, Nav in src/components/ui/) are a starting point — reuse them, extend them, or write new ones as the design calls for, but keep the same quality bar.
51	- Multi-page: this is a single-page app. Build distinct sections/routes as components conditionally rendered or scrolled to, not separate .html files.
52	
53	## Hard constraints — these break the sandboxed build/serve, not just style
54	- NO external requests. No CDN scripts, no Google Fonts, no remote images, no
55	  fetch/XHR to other origins — the CSP blocks all of them at serve time.
56	- Only the dependencies already in package.json exist (react, react-dom). You
57	  cannot add packages — there is no install step per generation.
58	- Images are inline SVG, CSS gradients, or data: URIs. Never <img src="https://...">.
59	
60	## Assets — use these instead of drawing everything by hand
61	Kodely ships a catalogue of ~460 inlinable assets: icons (contact, social, commerce, food, trades, UI), country flags, curated gradients, mesh backgrounds, grain textures, section dividers, CSS patterns and initials avatars. All of them are safe under the CSP because none of them fetch anything.
62	Search the catalogue with the find_assets tool — pass what you need in plain words ("plumber wrench icon", "warm sunset gradient", "wave divider") and paste the source it returns.
63	Reach for the catalogue before hand-writing SVG path data: the results are cleaner and more consistent than improvised geometry, and they cost far fewer tokens. Hand-write only when nothing fits.
64	- Fonts come from the system stack (ui-sans-serif, -apple-system, "Segoe UI", Inter, sans-serif). No @import, no <link>, and no @font-face — not even with a base64 data: URI. The CSP sets no font-src, so fonts fall back to default-src 'self', which does NOT allow data: (unlike img-src, which does). A base64 font is blocked exactly like a remote one.
65	
66	## Quality bar
67	Ship something that looks designed, not templated. Real, specific copy for the
68	subject at hand — never "Lorem ipsum" and never placeholder headings like
69	"Your Title Here". Responsive down to 380px. Semantic HTML, labelled form
70	controls, sufficient colour contrast, and a visible :focus style. Include a
71	dark-mode treatment unless the brief implies otherwise. Give the page one
72	distinctive visual idea rather than a generic hero-plus-three-cards.
73	
74	## Never invent facts about a real business
75	"Specific copy" means specific to the SUBJECT, not invented details about a
76	real business. Never fabricate: street addresses, phone numbers, email
77	addresses, opening hours, prices, staff names, years in business, customer
78	counts, awards, certifications, review scores, or testimonials.
79	
80	These end up on a real business's public website. An invented phone number is
81	a real number belonging to somebody else; invented opening hours send real
82	customers to a closed door; an invented testimonial is a fabricated
83	endorsement. This outranks the "no placeholder text" rule above — when you
84	don't know a fact, that rule does not license you to make one up.
85	
86	Use a clearly-bracketed placeholder instead: [your phone number],
87	[your address], [your opening hours]. A bracket is an obvious prompt to fill
88	something in; a plausible-looking invention is one nobody notices before
89	publishing. Invent freely for anything that is genuinely a design choice —
90	headlines, section copy, taglines, colour, imagery.
91	
92	## Never build something that only pretends to work
93	There is no backend, so anything needing a server cannot function. Do not
94	build a contact form, booking form, newsletter signup, login, cart or checkout
95	that appears functional — a form that silently discards a real enquiry is
96	worse than no form.
97	
98	Where the brief asks for one, use a real alternative that works with no
99	server: a mailto: link, a tel: link, or a prominent [link to your booking
100	system]. If you show such a control as a visual element, its label must make
101	the destination obvious ("Email us", "Call now"), never "Submit" or "Send".
102	
103	## Editing an existing site
104	You are given the current source files. Change only what the request calls
105	for — do not restyle or restructure components the user did not ask about.
106	
107	## Working style
108	Write the files first, then finish with two or three sentences telling the user
109	what you built and what they might want to change next. Do not narrate each file
110	as you write it, and do not paste code into your reply — the user sees a live
111	preview of the result.`;
112	
113	const TOOLS: Anthropic.Tool[] = [
114	  {
115	    name: "write_file",
116	    description:
117	      "Create a file or replace its entire contents. Always pass the complete final file, never a fragment or a diff.",
118	    input_schema: {
119	      type: "object",
120	      properties: {
121	        path: {
122	          type: "string",
123	          description: "Project-relative path, e.g. 'index.html' or 'styles.css'. No leading slash.",
124	        },
125	        content: { type: "string", description: "The complete contents of the file." },
126	      },
127	      required: ["path", "content"],
128	    },
129	  },
130	  {
131	    name: "delete_file",
132	    description: "Delete a file that is no longer part of the site.",
133	    input_schema: {
134	      type: "object",
135	      properties: { path: { type: "string", description: "Project-relative path to delete." } },
136	      required: ["path"],
137	    },
138	  },
139	  {
140	    name: "find_assets",
141	    description:
142	      "Search Kodely's built-in asset catalogue (icons, country flags, gradients, mesh backgrounds, grain textures, section dividers, CSS patterns, initials avatars). Returns paste-ready source for each match. Everything it returns is inlinable and CSP-safe. Prefer this over hand-writing SVG path data.",
143	    input_schema: {
144	      type: "object",
145	      properties: {
146	        query: {
147	          type: "string",
148	          description:
149	            "Plain-words description, e.g. 'phone icon', 'warm sunset gradient', 'wave section divider', 'french flag'.",
150	        },
151	        kind: {
152	          type: "string",
153	          enum: [...ASSET_KINDS],
154	          description: "Optional filter to one kind of asset.",
155	        },
156	        limit: { type: "number", description: "Max results, default 6." },
157	      },
158	      required: ["query"],
159	    },
160	  },
161	];
162	
163	/** Reject path traversal and absolute paths before anything touches the DB. */
164	export function normalizePath(raw: string): string | null {
165	  const path = raw.trim().replace(/^\.?\//, "");
166	  if (!path || path.length > 200) return null;
167	  if (path.includes("..") || path.startsWith("/") || path.includes("\\")) return null;
168	  if (!/^[A-Za-z0-9._/-]+$/.test(path)) return null;
169	  return path;
170	}
171	
172	function describeFiles(files: FileMap): string {
173	  const paths = Object.keys(files);
174	  if (paths.length === 0) return "The project is empty — this is the first build.";
175	  return [
176	    "Current files in the project:",
177	    ...paths.map((p) => `\n--- ${p} ---\n${files[p]}`),
178	  ].join("\n");
179	}
180	
181	type RunOptions = {
182	  /** Prior turns, oldest first. */
183	  history: { role: "user" | "assistant"; content: string }[];
184	  request: string;
185	  files: FileMap;
186	  /** First build of a site vs a follow-up tweak — drives how hard we think. */
187	  kind: "create" | "edit";
188	  /** A reference image attached to this turn's request (vision input). */
189	  image?: { mediaType: string; data: string };
190	  /** Applies the write; returning false rejects it (e.g. bad path). */
191	  onWrite: (path: string, content: string) => Promise<boolean>;
192	  onDelete: (path: string) => Promise<boolean>;
193	  /**
194	   * Aborted when the client disconnects (tab closed, network drop). Actually
195	   * cancels the in-flight Anthropic request instead of letting it run to
196	   * completion for nobody — a disconnect shouldn't mean paying full price for
197	   * a generation no one will ever see the result of.
198	   */
199	  signal?: AbortSignal;
200	};
201	
202	/**
203	 * Runs the plan → generate → apply loop, streaming progress as it goes.
204	 * Token usage is accumulated across every turn so the caller can meter the
205	 * true cost of the build (including the repair turns, which we may not bill).
206	 */
207	// Which generation engine to use.
208	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
209	//                   real usage telemetry, real credit charges.
210	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
211	//                   subscription login. No metered spend, so no cost data and
212	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
213	// Defaults to `api` so a fresh clone never silently runs on someone's personal
214	// subscription; the environment opts in.
215	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
216	
217	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
218	  if (ENGINE === "sdk") {
219	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
220	    // authenticated this must fail loudly rather than quietly spend money on
221	    // the metered key the operator asked not to use.
222	    const { runAgentSdk } = await import("./agent-sdk");
223	    yield* runAgentSdk(opts, SYSTEM);
224	    return;
225	  }
226	
227	  const model = MODELS.builder;
228	  // Effort is the sharpest cost lever we have: a first build is a blank-page
229	  // design problem and earns `high`, while a targeted tweak lands the same
230	  // result at `medium` for a fraction of the thinking tokens.
231	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
232	
233	  const messages: Anthropic.MessageParam[] = [];
234	  for (const turn of opts.history) {
235	    messages.push({ role: turn.role, content: turn.content });
236	  }
237	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
238	  if (opts.image) {
239	    messages.push({
240	      role: "user",
241	      content: [
242	        {
243	          type: "image",
244	          source: {
245	            type: "base64",
246	            media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
247	            data: opts.image.data,
248	          },
249	        },
250	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
251	      ],
252	    });
253	  } else {
254	    messages.push({ role: "user", content: requestText });
255	  }
256	
257	  const totals = {
258	    inputTokens: 0,
259	    outputTokens: 0,
260	    cacheReadTokens: 0,
261	    cacheWriteTokens: 0,
262	  };
263	
264	  // Bounded so a confused model can never bill the user for an endless loop.
265	  const MAX_TURNS = 8;
266	
267	  for (let turn = 0; turn < MAX_TURNS; turn++) {
268	    if (opts.signal?.aborted) return;
269	
270	    const stream = anthropic.messages.stream(
271	      {
272	        model,
273	        max_tokens: 32_000,
274	        thinking: { type: "adaptive" },
275	        output_config: { effort },
276	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
277	        tools: TOOLS,
278	        messages,
279	      },
280	      { signal: opts.signal },
281	    );
282	
283	    for await (const event of stream) {
284	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
285	        yield { type: "text", text: event.delta.text };
286	      }
287	    }
288	
289	    const message = await stream.finalMessage();
290	    totals.inputTokens += message.usage.input_tokens ?? 0;
291	    totals.outputTokens += message.usage.output_tokens ?? 0;
292	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
293	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
294	
295	    if (message.stop_reason === "refusal") {
296	      throw new Error(
297	        "The request was declined. Try describing the site you want in different terms.",
298	      );
299	    }
300	
301	    const toolUses = message.content.filter(
302	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
303	    );
304	
305	    if (toolUses.length === 0) {
306	      yield { type: "usage", model, ...totals };
307	      return;
308	    }
309	
310	    messages.push({ role: "assistant", content: message.content });
311	
312	    const results: Anthropic.ToolResultBlockParam[] = [];
313	    for (const use of toolUses) {
314	      const input = use.input as {
315	        path?: string;
316	        content?: string;
317	        query?: string;
318	        kind?: string;
319	        limit?: number;
320	      };
321	
322	      // Handled before the path check below — this is the one tool that takes
323	      // no path, and running it through normalizePath would reject it outright.
324	      if (use.name === "find_assets") {
325	        yield { type: "progress", text: "Picking out icons and artwork" };
326	        const matches = findAssets(input.query ?? "", {
327	          kind: input.kind as AssetKind | undefined,
328	          limit: Math.min(Math.max(input.limit ?? 6, 1), 12),
329	        });
330	        results.push({
331	          type: "tool_result",
332	          tool_use_id: use.id,
333	          content: formatMatchesForTool(matches),
334	        });
335	        continue;
336	      }
337	
338	      const path = normalizePath(input.path ?? "");
339	
340	      if (!path) {
341	        results.push({
342	          type: "tool_result",
343	          tool_use_id: use.id,
344	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
345	          is_error: true,
346	        });
347	        continue;
348	      }
349	
350	      // Narrate before applying, so the line appears while the write is
351	      // happening rather than after it lands.
352	      const line = narrateTool(use.name, { path });
353	      if (line) yield { type: "progress", text: line };
354	
355	      if (use.name === "write_file") {
356	        const ok = await opts.onWrite(path, input.content ?? "");
357	        if (ok) yield { type: "file", path, action: "write" };
358	        results.push({
359	          type: "tool_result",
360	          tool_use_id: use.id,
361	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
362	          is_error: !ok,
363	        });
364	      } else if (use.name === "delete_file") {
365	        const ok = await opts.onDelete(path);
366	        if (ok) yield { type: "file", path, action: "delete" };
367	        results.push({
368	          type: "tool_result",
369	          tool_use_id: use.id,
370	          content: ok ? `Deleted ${path}.` : `${path} did not exist.`,
371	          is_error: false,
372	        });
373	      } else {
374	        results.push({
375	          type: "tool_result",
376	          tool_use_id: use.id,
377	          content: `Unknown tool ${use.name}.`,
378	          is_error: true,
379	        });
380	      }
381	    }
382	
383	    messages.push({ role: "user", content: results });
384	  }
385	
386	  yield { type: "usage", model, ...totals };
387	}
388

1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/**
15	 * New accounts start with enough to build and iterate on a real page.
16	 * Sized from measured real costs (2026-08-17): a full first build runs
17	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
18	 * 750 covers roughly one build plus 2-3 real edits.
19	 */
20	export const SIGNUP_GRANT = 750;
21	
22	export type Usage = {
23	  inputTokens: number;
24	  outputTokens: number;
25	  cacheReadTokens: number;
26	  cacheWriteTokens: number;
27	};
28	
29	/**
30	 * Micro-dollars of real model spend for a given usage on a given model.
31	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
32	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
33	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
34	 * 1e6, that computes cost in whole dollars instead and silently floors every
35	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
36	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
37	 */
38	export function costMicros(model: string, usage: Usage): number {
39	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
40	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
41	  return Math.round(
42	    perToken(rate.input, usage.inputTokens) +
43	      perToken(rate.output, usage.outputTokens) +
44	      perToken(rate.cacheRead, usage.cacheReadTokens) +
45	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
46	  );
47	}
48	
49	export function creditsFor(micros: number): number {
50	  // Zero measured cost means zero credits. The floor below exists so a real
51	  // but tiny cost never rounds down to free — it must NOT turn a build with no
52	  // metered spend at all into a 1-credit charge.
53	  //
54	  // This is not hypothetical: on the SDK engine a build whose telemetry is
55	  // missing reports 0 tokens and 0 micros (see meterUsage in lib/agent-sdk.ts),
56	  // and every one of those was being billed a credit for spend that provably
57	  // did not happen — inside the one module whose stated purpose is never doing
58	  // that. Found 2026-08-22 in a real ledger row.
59	  if (micros <= 0) return 0;
60	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
61	}
62	
63	export async function getBalance(userId: string): Promise<number> {
64	  const latest = await db.creditLedger.findFirst({
65	    where: { userId },
66	    orderBy: { createdAt: "desc" },
67	  });
68	  return latest?.balanceAfter ?? 0;
69	}
70	
71	export async function grantCredits(userId: string, amount: number, reason: string) {
72	  const balance = await getBalance(userId);
73	  return db.creditLedger.create({
74	    data: { userId, delta: amount, reason, balanceAfter: balance + amount },
75	  });
76	}
77	
78	/**
79	 * Charge for a SUCCESSFUL build. Never call this on a failed build — the whole
80	 * promise to the customer is that broken output is free.
81	 */
82	export async function chargeForBuild(userId: string, buildId: string, credits: number) {
83	  const balance = await getBalance(userId);
84	  await db.creditLedger.create({
85	    data: {
86	      userId,
87	      delta: -credits,
88	      reason: "build",
89	      buildId,
90	      balanceAfter: balance - credits,
91	    },
92	  });
93	  return balance - credits;
94	}
95	
96	/**
97	 * Pre-flight estimate shown BEFORE the user spends anything. Deliberately a
98	 * range derived from observed build sizes, not a fake precise number.
99	 *
100	 * Numbers corrected 2026-08-21. The previous 8-30 / 3-15 ranges predated the
101	 * costMicros fix and understated real spend by roughly an order of magnitude —
102	 * on a product whose headline promise is no bill shock, an estimate that low
103	 * is worse than showing nothing.
104	 *
105	 * The honest state of our evidence: measured builds have come in at ~144
106	 * credits (2026-08-17) and ~472 credits (2026-08-21, a first build of a
107	 * tradesman site via the eval harness). That is a 3x spread across two
108	 * samples, so the range below is deliberately wide rather than falsely
109	 * precise, and skews high — quoting low and charging high is the exact
110	 * failure this whole module exists to prevent.
111	 *
112	 * REPLACE THIS with real percentiles once the eval harness has run a full
113	 * sweep (scripts/eval). Two data points is not a distribution.
114	 */
115	export function estimateCredits(kind: "create" | "edit"): { low: number; high: number } {
116	  return kind === "create" ? { low: 120, high: 550 } : { low: 60, high: 300 };
117	}
118	
119	/**
120	 * Fallback when a user has no build history to average. Sits near the upper
121	 * of our two measurements on purpose: this drives "about N more builds", and
122	 * over-promising remaining builds is how someone hits zero mid-build.
123	 */
124	const TYPICAL_BUILD_CREDITS = 400;
125	
126	/**
127	 * What a build actually costs THIS user, averaged over their recent successful
128	 * builds. Personal history beats a global constant: someone building one-page
129	 * sites and someone building ten-page sites deserve different answers to
130	 * "how many builds do I have left?".
131	 */
132	export async function averageBuildCredits(userId: string): Promise<number> {
133	  const recent = await db.build.findMany({
134	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
135	    orderBy: { createdAt: "desc" },
136	    take: 10,
137	    select: { creditsCharged: true },
138	  });
139	  if (recent.length === 0) return TYPICAL_BUILD_CREDITS;
140	  const total = recent.reduce((sum, b) => sum + b.creditsCharged, 0);
141	  return Math.max(1, Math.round(total / recent.length));
142	}
143	
144	// ── Self-imposed spend cap ────────────────────────────────────────────────
145	// Point 4 of the anti-bill-shock contract. The three rules above stop us from
146	// OVERCHARGING for a given build; none of them stop a user from running fifty
147	// builds in an afternoon and being genuinely shocked by the total. A ceiling
148	// the user sets themselves is the honest answer, and it is the one guard a
149	// competitor's $607-against-a-$25-plan incident would have needed.
150	//
151	// Rolling 30 days, not calendar month, so there is no "reset day" to game and
152	// no cliff where a cap silently stops protecting someone mid-month.
153	
154	const CAP_WINDOW_DAYS = 30;
155	
156	export type SpendCapStatus = {
157	  /** NULL when the user has set no cap. */
158	  cap: number | null;
159	  spent: number;
160	  /** Credits still available under the cap; Infinity when uncapped. */
161	  remaining: number;
162	  reached: boolean;
163	};
164	
165	/** Credits spent on builds in the rolling window. Grants are excluded. */
166	export async function spentInWindow(userId: string): Promise<number> {
167	  const since = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);
168	  const { _sum } = await db.creditLedger.aggregate({
169	    where: { userId, createdAt: { gte: since }, delta: { lt: 0 } },
170	    _sum: { delta: true },
171	  });
172	  // Deltas are negative for spend; report it as a positive number.
173	  return Math.abs(_sum.delta ?? 0);
174	}
175	
176	export async function getSpendCapStatus(userId: string): Promise<SpendCapStatus> {
177	  const user = await db.user.findUnique({
178	    where: { id: userId },
179	    select: { spendCapCredits: true },
180	  });
181	  const cap = user?.spendCapCredits ?? null;
182	
183	  if (cap === null) {
184	    return { cap: null, spent: 0, remaining: Infinity, reached: false };
185	  }
186	
187	  const spent = await spentInWindow(userId);
188	  return { cap, spent, remaining: Math.max(0, cap - spent), reached: spent >= cap };
189	}
