1	import Stripe from "stripe";
2	
3	// ── Money-path safety rules for this file ──────────────────────────────────
4	// 1. Credit packs are a fixed server-side table, keyed by an opaque pack id.
5	//    A client can only ever say WHICH pack it wants — never an amount, a
6	//    price, or a credit count. This is the same class of bug that hit Nxeon's
7	//    hosting checkout (displayed price != charged price); the fix there was
8	//    "never trust a client-supplied number", and it applies here identically.
9	// 2. Credits are granted ONLY from the webhook, after Stripe confirms payment
10	//    — never from the client-side checkout-success redirect, which a user can
11	//    hit or forge without ever having paid.
12	// 3. Every webhook event is idempotency-guarded via StripeEvent (see schema)
13	//    — Stripe retries on any non-2xx, so this must be safe to receive twice.
14	
15	export type CreditPack = {
16	  id: string;
17	  credits: number;
18	  priceUsdCents: number;
19	  label: string;
20	};
21	
22	// $1 = 500 credits list price (matches MICROS_PER_CREDIT in lib/credits.ts —
23	// 500 credits * 2000 micros = $1.00), packs get a modest discount at volume.
24	export const CREDIT_PACKS: CreditPack[] = [
25	  { id: "starter", credits: 500, priceUsdCents: 900, label: "500 credits — $9" },
26	  { id: "builder", credits: 2500, priceUsdCents: 4000, label: "2,500 credits — $40" },
27	  { id: "pro", credits: 6000, priceUsdCents: 9000, label: "6,000 credits — $90" },
28	];
29	
30	export function getPack(packId: string): CreditPack | undefined {
31	  return CREDIT_PACKS.find((p) => p.id === packId);
32	}
33	
34	/** True once real Stripe keys are configured. Billing UI/routes degrade gracefully until then. */
35	export function billingEnabled(): boolean {
36	  return !!process.env.STRIPE_SECRET_KEY && !!process.env.STRIPE_WEBHOOK_SECRET;
37	}
38	
39	let client: Stripe | null = null;
40	
41	export function stripe(): Stripe {
42	  if (!process.env.STRIPE_SECRET_KEY) {
43	    throw new Error("Stripe is not configured (STRIPE_SECRET_KEY unset).");
44	  }
45	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
46	  return client;
47	}
