73	/**
74	 * Ensure a served HTML document has a real title, a description, canonical
75	 * and OG/Twitter tags. Only fills gaps — anything the builder already wrote
76	 * is left exactly as-is, since it had the site's actual content in view and
77	 * this function does not.
78	 */
79	export function applySeo(html: string, opts: { projectName: string; baseUrl: string }): string {
80	  const { projectName, baseUrl } = opts;
81	  if (!/<head[\s>]/i.test(html)) return html; // not a full document; leave alone
82	
83	  let out = html;
84	
85	  // 1. Title — replace the placeholder, or add one if missing entirely.
86	  const titleMatch = out.match(/<title>([\s\S]*?)<\/title>/i);
87	  const currentTitle = titleMatch?.[1]?.trim();
88	  const title = !currentTitle || currentTitle === PLACEHOLDER_TITLE ? projectName : currentTitle;
89	  if (titleMatch) {
90	    if (currentTitle !== title) {
91	      out = out.replace(/<title>[\s\S]*?<\/title>/i, `<title>${escapeHtml(title)}</title>`);
92	    }
93	  } else {
94	    out = out.replace(/<head([^>]*)>/i, `<head$1>\n    <title>${escapeHtml(title)}</title>`);
95	  }
96	
97	  const inject: string[] = [];
98	
99	  // Upsert a <meta>/<link>: fill it when the tag is absent OR present with an
100	  // empty value. The foundation ships empty `content=""` scaffolding to show
101	  // the builder what to write, so "tag exists" alone is not good enough — an
102	  // existence-only check would leave those empty forever.
103	  const upsert = (attrRe: RegExp, valueAttr: "content" | "href", value: string, tag: string) => {
104	    const existing = out.match(attrRe);
105	    if (!existing) {
106	      inject.push(tag);
107	      return;
108	    }
109	    const valRe = new RegExp(`${valueAttr}=["']([^"']*)["']`, "i");
110	    const current = existing[0].match(valRe)?.[1];
111	    if (current === undefined || current.trim() === "") {
112	      out = out.replace(existing[0], tag);
113	    }
114	  };
115	
116	  const desc = `${title} — built with Kodely.`;
117	  upsert(
118	    /<meta\s+name=["']description["'][^>]*>/i,
119	    "content",
120	    desc,
121	    `<meta name="description" content="${escapeHtml(desc)}" />`,
122	  );
123	  upsert(
124	    /<link\s+rel=["']canonical["'][^>]*>/i,
125	    "href",
126	    baseUrl,
127	    `<link rel="canonical" href="${escapeHtml(baseUrl)}" />`,
128	  );
129	  upsert(
130	    /<meta\s+property=["']og:title["'][^>]*>/i,
131	    "content",
132	    title,
133	    `<meta property="og:title" content="${escapeHtml(title)}" />`,
134	  );
135	  upsert(
136	    /<meta\s+property=["']og:description["'][^>]*>/i,
137	    "content",
138	    desc,
139	    `<meta property="og:description" content="${escapeHtml(desc)}" />`,
140	  );
141	  upsert(
142	    /<meta\s+property=["']og:type["'][^>]*>/i,
143	    "content",
144	    "website",
145	    `<meta property="og:type" content="website" />`,
146	  );
147	  upsert(
148	    /<meta\s+property=["']og:url["'][^>]*>/i,
149	    "content",
150	    baseUrl,
151	    `<meta property="og:url" content="${escapeHtml(baseUrl)}" />`,
152	  );
153	  upsert(
154	    /<meta\s+name=["']twitter:card["'][^>]*>/i,
155	    "content",
156	    "summary_large_image",
157	    `<meta name="twitter:card" content="summary_large_image" />`,
158	  );
159	
160	  if (inject.length) {
161	    out = out.replace(/<\/head>/i, `  ${inject.join("\n    ")}\n  </head>`);
162	  }
163	
164	  // Crawlers reject relative og:image, so absolutise whatever the builder set.
165	  out = out.replace(
166	    /(<meta\s+property=["']og:image["']\s+content=["'])([^"']+)(["'])/gi,
167	    (_m, pre, url, post) => `${pre}${escapeHtml(absolutise(url, baseUrl))}${post}`,
168	  );
169	
170	  return out;
171	}
