1	// Exists because /api/site/[slug]/... serves published files to the public internet with no auth — a secret pasted or echoed into generated content becomes public and permanent the moment it's published, so this scans draft files as the last gate before that happens.
2	
3	const DATA_URI_RE = /data:[a-zA-Z0-9+.\-/]+;base64,[A-Za-z0-9+/=]+/g;
4	
5	function redact(value: string): string {
6	  return value.length <= 6 ? `${value}…` : `${value.slice(0, 6)}…`;
7	}
8	
9	interface SecretPattern {
10	  kind: string;
11	  regex: RegExp;
12	}
13	
14	const PATTERNS: SecretPattern[] = [
15	  { kind: "AWS access key ID", regex: /AKIA[0-9A-Z]{16}/g },
16	  {
17	    kind: "API key/secret assignment",
18	    regex: /(?:api[_-]?key|secret|token|password|passwd|pwd)\s*[:=]\s*['"]([A-Za-z0-9_-]{20,})['"]/gi,
19	  },
20	  { kind: "OpenAI/Anthropic-style secret key", regex: /sk-(?:live-|test-)?[A-Za-z0-9]{20,}/g },
21	  { kind: "Stripe secret key", regex: /sk_(?:live|test)_[A-Za-z0-9]{20,}/g },
22	  { kind: "Google API key", regex: /AIza[0-9A-Za-z_-]{35}/g },
23	  { kind: "Private key (PEM)", regex: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/g },
24	  { kind: "JWT", regex: /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g },
25	];
26	
27	export function scanForSecrets(
28	  files: { path: string; content: string }[],
29	): { path: string; match: string; kind: string }[] {
30	  const findings: { path: string; match: string; kind: string }[] = [];
31	
32	  for (const file of files) {
33	    // Strip data: URIs before scanning so a long base64 image/font blob can't
34	    // coincidentally trip a pattern — those bytes are assets, not credentials.
35	    const scannable = file.content.replace(DATA_URI_RE, "");
36	
37	    for (const { kind, regex } of PATTERNS) {
38	      regex.lastIndex = 0;
39	      let m: RegExpExecArray | null;
40	      while ((m = regex.exec(scannable)) !== null) {
41	        const value = m[1] ?? m[0];
42	        findings.push({ path: file.path, match: redact(value), kind });
43	      }
44	    }
45	  }
46	
47	  return findings;
48	}
